style.css:
/* Dark Coquette Theme ♡ */

body {
  background-color: #171316 !important;
  color: #F2DCE5 !important;
  font-family: Arial, sans-serif;
}

h1, h2, h3, h4 {
  color: #E6B9CA !important;
  letter-spacing: 1px;
}

p {
  color: #D2C0C8 !important;
}

a {
  color: #D9A6B8 !important;
}

a:hover {
  color: #F2DCE5 !important;
}

button {
  background-color: #593B49 !important;
  color: #F2DCE5 !important;
  border: 1px solid #A66F83 !important;
  border-radius: 12px !important;
}

button:hover {
  background-color: #80566A !important;
}

input, textarea, select {
  background-color: #292027 !important;
  color: #F2DCE5 !important;
  border: 1px solid #80566A !important;
}

::selection {
  background-color: #A66F83 !important;
  color: #FFFFFF !important;
}

::-webkit-scrollbar {
  width: 7px;
}

::-webkit-scrollbar-track {
  background: #171316;
}

::-webkit-scrollbar-thumb {
  background: #80566A;
  border-radius: 10px;
}
